	var lastInfo tokenCountInfo

	for _, line := range lines {
		if line.Type != eventTypeEventMsg {
			continue
		}

		var payload eventMsgPayload
		if err := json.Unmarshal(line.Payload, &payload); err != nil {
			continue
		}

